package com.sumedha.commerce.auth.security;
import com.sumedha.commerce.auth.config.AuthProperties; import com.sumedha.commerce.auth.entity.User; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*;
@Service public class JwtService { private final AuthProperties p; private final SecretKey key; public JwtService(AuthProperties p){this.p=p; if(p.secret()==null||p.secret().getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalStateException("AUTH_JWT_SECRET must be at least 32 bytes"); key=Keys.hmacShaKeyFor(p.secret().getBytes(StandardCharsets.UTF_8));} public String create(User u){Instant now=Instant.now();return Jwts.builder().subject(u.getId().toString()).issuer(p.issuer()).claim("role",u.getRole().name()).issuedAt(Date.from(now)).expiration(Date.from(now.plus(p.accessTokenExpiration()))).signWith(key).compact();} public Jws<Claims> parse(String token){return Jwts.parser().verifyWith(key).requireIssuer(p.issuer()).build().parseSignedClaims(token);} }
